// CPU state and helpers for code generated by tools/recomp.py.
// Generated blocks are plain functions: they change this state and set c.pc to where the
// program continues. No ARM code is interpreted at run time.
#pragma once

#include <cstdint>

using u8 = std::uint8_t;
using u16 = std::uint16_t;
using u32 = std::uint32_t;
using s8 = std::int8_t;
using s16 = std::int16_t;
using s32 = std::int32_t;
using u64 = std::uint64_t;
using s64 = std::int64_t;

enum Mode : u32 {
    kUsr = 0x10, kFiq = 0x11, kIrq = 0x12, kSvc = 0x13, kAbt = 0x17, kUnd = 0x1B, kSys = 0x1F,
};

struct Cpu {
    u32 r[16] = {};
    u32 n = 0, z = 0, cf = 0, v = 0, q = 0;  // flags, each 0 or 1
    u32 mode = kSvc;
    u32 irq_off = 1, fiq_off = 1, thumb = 0;
    u32 spsr = 0;
    u32 pc = 0;  // where the next block starts

    u32 bank_r13[6] = {}, bank_r14[6] = {}, bank_spsr[6] = {};
    u32 fiq_r8_12[5] = {}, usr_r8_12[5] = {};

    u32 cpsr() const;
    void set_cpsr(u32 value, u32 mask);
    void switch_mode(u32 new_mode);
    void exception_return(u32 target);  // movs pc / ldm ^ with pc: restores CPSR from SPSR
    u32 user_reg(int index) const;
    void set_user_reg(int index, u32 value);
    void branch_exchange(u32 target) {  // bx, blx, ldr pc: bit 0 selects Thumb
        thumb = target & 1;
        pc = target & (thumb ? ~1u : ~3u);
    }
};

// Memory, implemented in memory.cpp.
u8 rd8(u32 addr);
u16 rd16(u32 addr);
u32 rd32(u32 addr);
void wr8(u32 addr, u8 value);
void wr16(u32 addr, u16 value);
void wr32(u32 addr, u32 value);

// Things the generated code hands to the runtime.
[[noreturn]] void runtime_abort(const char* reason, u32 addr);
void software_interrupt(Cpu& c, u32 number);
void cp15_write(Cpu& c, u32 op1, u32 crn, u32 crm, u32 op2, u32 value);
u32 cp15_read(Cpu& c, u32 op1, u32 crn, u32 crm, u32 op2);

// ARM loads rotate a misaligned word.
inline u32 ldr_rotated(u32 addr) {
    const u32 value = rd32(addr & ~3u);
    const u32 shift = (addr & 3) * 8;
    return shift ? (value >> shift) | (value << (32 - shift)) : value;
}

// Conditions. Index is the ARM condition field.
inline bool cond(const Cpu& c, u32 code) {
    switch (code) {
        case 0: return c.z;
        case 1: return !c.z;
        case 2: return c.cf;
        case 3: return !c.cf;
        case 4: return c.n;
        case 5: return !c.n;
        case 6: return c.v;
        case 7: return !c.v;
        case 8: return c.cf && !c.z;
        case 9: return !c.cf || c.z;
        case 10: return c.n == c.v;
        case 11: return c.n != c.v;
        case 12: return !c.z && c.n == c.v;
        case 13: return c.z || c.n != c.v;
        default: return true;
    }
}

inline void set_nz(Cpu& c, u32 value) {
    c.n = value >> 31;
    c.z = value == 0;
}

// a + b + carry with all flags. Subtraction passes ~b and carry 1 (or the C flag for sbc).
inline u32 add_flags(Cpu& c, u32 a, u32 b, u32 carry) {
    const u64 wide = u64(a) + u64(b) + carry;
    const u32 result = u32(wide);
    c.cf = u32(wide >> 32);
    c.v = ((a ^ result) & (b ^ result)) >> 31;
    set_nz(c, result);
    return result;
}

// Barrel shifter. kind: 0 lsl, 1 lsr, 2 asr, 3 ror. carry receives the shifter carry out.
// By an immediate, encoded amounts follow the ARM rules (lsr #0 means 32, ror #0 means rrx).
inline u32 shift_imm(u32 kind, u32 value, u32 amount, u32& carry, u32 carry_in) {
    carry = carry_in;
    switch (kind) {
        case 0:
            if (amount == 0) return value;
            carry = (value >> (32 - amount)) & 1;
            return value << amount;
        case 1:
            if (amount == 0) { carry = value >> 31; return 0; }
            carry = (value >> (amount - 1)) & 1;
            return value >> amount;
        case 2:
            if (amount == 0) {
                carry = value >> 31;
                return u32(s32(value) >> 31);
            }
            carry = (value >> (amount - 1)) & 1;
            return u32(s32(value) >> amount);
        default:
            if (amount == 0) {  // rrx
                carry = value & 1;
                return (carry_in << 31) | (value >> 1);
            }
            carry = (value >> (amount - 1)) & 1;
            return (value >> amount) | (value << (32 - amount));
    }
}

// By a register: only the low byte counts, and 0 leaves value and carry alone.
inline u32 shift_reg(u32 kind, u32 value, u32 amount, u32& carry, u32 carry_in) {
    amount &= 0xFF;
    carry = carry_in;
    if (amount == 0) return value;
    switch (kind) {
        case 0:
            if (amount < 32) { carry = (value >> (32 - amount)) & 1; return value << amount; }
            carry = amount == 32 ? value & 1 : 0;
            return 0;
        case 1:
            if (amount < 32) { carry = (value >> (amount - 1)) & 1; return value >> amount; }
            carry = amount == 32 ? value >> 31 : 0;
            return 0;
        case 2:
            if (amount < 32) { carry = (value >> (amount - 1)) & 1; return u32(s32(value) >> amount); }
            carry = value >> 31;
            return u32(s32(value) >> 31);
        default: {
            const u32 rotate = amount & 31;
            if (rotate == 0) { carry = value >> 31; return value; }
            carry = (value >> (rotate - 1)) & 1;
            return (value >> rotate) | (value << (32 - rotate));
        }
    }
}

inline u32 count_leading_zeros(u32 value) {
    u32 count = 0;
    while (count < 32 && !(value & (0x80000000u >> count))) ++count;
    return count;
}

inline s32 saturate(s64 value, u32& q) {
    if (value > 0x7FFFFFFFLL) { q = 1; return 0x7FFFFFFF; }
    if (value < -0x80000000LL) { q = 1; return s32(0x80000000u); }
    return s32(value);
}

using BlockFn = void (*)(Cpu&);
BlockFn find_block(u32 pc_and_thumb);  // generated
